// Small guards for text and URLs that come from the database (campaign pages are user-supplied).

export { escapeHtml } from '../../oss/donation-widgets/src/lib/format';

/** The URL if it is http(s), else null: never put a `javascript:` or `data:` URL into an href. */
export function safeHttpUrl(url: unknown): string | null {
  if (typeof url !== 'string') return null;
  try {
    const u = new URL(url);
    return u.protocol === 'https:' || u.protocol === 'http:' ? u.href : null;
  } catch {
    return null;
  }
}

/** A CSS `url("…")` value for an http(s) image, or '' (the string is quoted, so it cannot close the rule). */
export function cssImageUrl(url: unknown): string {
  const safe = safeHttpUrl(url);
  return safe ? `url(${JSON.stringify(safe)})` : '';
}
